from pathlib import Path
r=Path(__file__).resolve().parents[1]
def change(rel, old, new):
 p=r/rel; s=p.read_text(); n=s.count(old)
 if n!=1: raise ValueError(f'{rel}: expected 1, found {n}: {old[:72]}')
 p.write_text(s.replace(old,new))
